import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AZ everyday-crime stories.
extension FollowUpCases {
    static let batchAZ: [CaseTemplate] = [kioskSmash, firecrackerBox, dumpsterAgain, shelterAgain, sealcoatSecond, boosterTwo, hotelPoolAgain, boatAgain, scooterAgain, gymCubby, garagePass, fakeDoctorLetter, churchBakeSale, motelLamps, karaokeAgain, hydrantAgain, tennisCourtSkate, daycareFenceLoiter, registerShove, barricadeTaken, ebayEmpty, fittingRoomTwo, lotGateAgain, wifiAgain, curbBed, barrelAgain, paradeAgain, receptionCrash, scooterTwo, pokerChips, tithePlate, fakeTempTag, hydroPillsAgain, bootsOut, fakePlateSticker, scooterRiver, hedgeCut, redirectedPackages, cardsFound, parkFightTwo, barberDeposit, duckCoop, photographerDeposit, shovelDriveway, refundGroceries, storeGrabRun, paramedicSpit, quadTrail, lostCatReward, dumpTruckDieselAgain]

    static let kioskSmash = SmallCases.make(
        key: "story.followup.kioskSmash",
        category: .property,
        headlines: ["Self-Service Kiosk Smashed After Payment Error"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a hospital, causing damage of $890, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} smashed a self-service payment kiosk after it rejected a card.",
        state: [E(.video, 3, "Lobby Camera", "{D} slams a fist into the screen.")],
        defense: [E(.statement, 1, "Error", "{DL} says the kiosk charged twice.")],
        role: "Hospital security guard",
        exam: [.direct("Please tell the jury what you do at the hospital.", "\"I'm a security guard at the hospital. I work the main lobby, help visitors find their way, and keep an eye on the equipment and entrances.\""), .direct("What did you see at the kiosk that day?", "\"I heard a loud bang and turned around. {D} was standing at the payment kiosk with a fist against the screen, and the glass had cracked.\""), .direct("What does the lobby camera show?", "\"It shows {DL} at the kiosk for a few minutes, tapping the screen, and then pulling back and slamming a fist into it.\""), .direct("How badly was the kiosk damaged?", "\"The screen cracked in two places and the machine stopped working. The hospital's estimate to replace the screen and the unit was $890.\""), .direct("What did you do after the blow?", "\"I walked over, asked {D.him} to step back, and stayed with {D.him} in the lobby until the deputies arrived.\""), .direct("How did {DL} behave when you approached?", "\"{D.He} was angry and out of breath, but {D.he} stepped back when I asked and sat on a bench without a fight.\""), .cross("Did {DL} tell you why the kiosk made {D.him} angry?", "\"Yes. {D.He} told me it had charged {D.him} twice for the same visit and then wouldn't take the card.\""), .cross("Did you check whether the kiosk had a double charge on record?", "\"I looked at the screen log afterward, and there were two charges for the same copay, one right after the other.\""), .cross("Did {DL} try to leave before the deputies arrived?", "\"No. {D.He} stayed on the bench, answered my questions and even offered to pay for the screen.\""), .cross("Did anyone get hurt when the screen cracked?", "\"No. There were people nearby, but nobody was struck and no glass fell out of the frame.\""), .cross("Has {DL} ever damaged anything in your lobby before?", "\"Not that I know of. This was the first time I'd seen {D.him} at the kiosks.\"")],
        theory: ("{D} slammed a fist into a hospital payment kiosk and cracked the screen.", "A billing error charged {DL} twice and then rejected the card, and the anger came from that, not from any plan to damage property."),
        allocution: "\"That kiosk charged me twice and then rejected my card, and I lost my temper and smashed it. I've been in this courtroom before, and I knew better. I'll pay for the machine and take the double charge up with the company the right way.\"",
        truths: ("{DL} was charged twice for the same visit, and the screen cracked in two places from a single blow.", "The kiosk's own receipt shows two charges for one copay, which is what set the frustration off."),
        defendant: [.direct("Did you hit the kiosk screen?", "\"Yes, I did. I slammed my fist into it, and I'm not going to pretend otherwise. I lost my temper in that moment.\""), .direct("What happened before that?", "\"I was paying a copay on the kiosk, and it charged me twice. When I tried to fix it, it rejected my card.\""), .direct("How much was charged to your account?", "\"The copay was charged two times, so I was out double the amount, and I had very little left to cover rent that week.\""), .direct("Why did you hit the screen?", "\"I was frustrated and scared about the money. I'd tried the screen several times, and nothing worked, and I just snapped.\""), .direct("What did you do after the screen cracked?", "\"I stepped back, apologized to the guard and sat down. I told him I'd pay for the damage and stayed there for the deputies.\""), .direct("What do you plan to do about the damage?", "\"I will pay for the screen, and I'll go to the billing office to dispute the double charge the proper way.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I knew better. I've worked on my temper since then, and I still failed that day.\""), .cross("The screen cracked in two places, didn't it?", "\"Yes. I saw the cracks right away, and I felt sick about it. I shouldn't have swung at all.\""), .cross("You could have gone to the billing desk, couldn't you?", "\"I could have gone there, no question. The desk was thirty feet away, and I walked right past it.\""), .cross("Nobody forced you to hit the machine, did they?", "\"No. It was my own decision, and I take full responsibility for it.\""), .cross("The damage came to $890, didn't it?", "\"That's the figure I was given, and I'm prepared to pay it.\"")],
        openings: ("At noon, a self-service payment kiosk in a hospital lobby rejected a card, and the lobby camera shows {D} slam a fist into the screen. The screen cracked in two places, causing $890 in damage, and {DL} was no stranger to this courtroom after {PRIORDATE} in the case known as {PRIOR}.", "{DL} does not dispute hitting the screen. The kiosk had charged {D.him} twice and then rejected the card, and the defense asks you to weigh a billing error against a moment of temper when you decide what this was."),
        closings: ("The lobby camera is clear. {D} slammed a fist into a kiosk screen and it cracked, costing the hospital $890. This is not {DL}'s first time here, since {PRIORDATE} brought {D.him} in once already on the earlier matter, {PRIOR}. Frustration with a machine does not excuse breaking it.", "{DL} was charged twice and then told the card was rejected. A fist to a screen in a moment of anger, over a billing error the hospital's own machine made, is not a plan to destroy property."),
        timeline: [(0, "Noon: the kiosk charges {D}'s card twice and then rejects it."), (0, "12:03 p.m.: {D} slams a fist into the screen and it cracks."), (0, "12:10 p.m.: security keeps {D} in the lobby until deputies arrive.")],
        identified: "Lobby Camera",
        mood: .indifferent)

    static let firecrackerBox = SmallCases.make(
        key: "story.followup.firecrackerBox",
        category: .property,
        headlines: ["Firecracker Splits Apartment Mailbox Bank"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a landlord, causing damage of $540, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} set off firecrackers in an apartment mailbox bank.",
        state: [E(.video, 3, "Lobby Camera", "{D} lights a fuse and leaves.")],
        defense: [E(.statement, 1, "Prank", "{DL} says it was a prank.")],
        role: "Landlord",
        exam: [.direct("Please tell the jury about your building.", "\"I own and manage an apartment building with about forty units. I live nearby, and I deal with repairs, residents' complaints and anything that goes wrong in the lobby.\""), .direct("What did you find that morning?", "\"A resident called me about the mailboxes. The metal doors on a whole bank of boxes were split open, and there were scorch marks around them.\""), .direct("What did the damage look like?", "\"The firecracker had burst inside one box and pushed outward. Three boxes had split seams, and the doors wouldn't lock anymore.\""), .direct("What did the lobby camera show?", "\"It shows {D} walking in at midnight, bending down at the mailboxes, lighting something, and walking out quickly before the burst.\""), .direct("How much did it cost to repair?", "\"We had to replace the box faces and the locks. The total came to $540, and residents couldn't get mail for several days.\""), .direct("Did the damage affect your tenants?", "\"Yes. Some mail was scorched, and a few people had to ask the post office to hold their deliveries until the locks were replaced.\""), .cross("Was anyone in the lobby when the firecracker burst?", "\"No. The camera shows the lobby empty before and after, and nobody was hurt that night.\""), .cross("Did {DL} live in your building?", "\"No, {D.he} didn't. I'd never seen {D.him} before the deputies showed me the footage.\""), .cross("Was there a fire after the burst?", "\"No. There were some scorch marks, but nothing caught fire, and I didn't need the fire department.\""), .cross("Did {DL} come back to apologize?", "\"I heard through the deputies that {D.he} wanted to. I haven't spoken to {D.him} myself.\""), .cross("Have you had other problems with vandals in the lobby?", "\"Occasionally, mostly graffiti. Nothing before had involved fireworks.\"")],
        theory: ("{D} lit a firecracker in an apartment mailbox bank and walked away as it burst.", "It was a prank that went too far, and nobody was nearby or meant to be hurt."),
        allocution: "\"It was a prank, and I didn't think about what firecrackers would do to a bank of mailboxes in an apartment hallway. I've been in this courtroom before, and I should have learned. I'll pay for the damage and apologize to the residents.\"",
        truths: ("The camera shows {DL} light the fuse with a lighter and walk away before the burst.", "No one was in the lobby or near the mailboxes when the firecracker went off."),
        defendant: [.direct("Did you light the firecracker in the mailbox bank?", "\"Yes, I did. It was a stupid prank, and I put it in an empty box and lit it.\""), .direct("What were you thinking at the time?", "\"I wasn't thinking much at all. I thought it would be a loud pop and a laugh, and I didn't consider what it would do.\""), .direct("Why were you at that building at midnight?", "\"I was walking home from a friend's place and cut through the lobby. I'd been drinking a little and was feeling foolish.\""), .direct("Did you check that no one was nearby?", "\"I looked around and saw nobody in the lobby, so I thought it was safe. I know that doesn't excuse it.\""), .direct("What happened after it went off?", "\"I heard the bang from the street and kept walking. I didn't go back, and I regret that I didn't see how bad the damage was.\""), .direct("What do you plan to do about the damage?", "\"I'll pay the landlord for the boxes and apologize to the residents who couldn't get their mail.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I should have learned from that. I'm embarrassed to be here again.\""), .cross("A firecracker in a metal box could have hurt someone, couldn't it?", "\"Yes, it could have. Luckily, no one was there, and I'm thankful for that.\""), .cross("You left the scene without telling anyone, didn't you?", "\"I did. I was embarrassed, and I walked away instead of facing it.\""), .cross("The lobby camera clearly shows you, doesn't it?", "\"It does. I'm the person lighting the fuse, and I won't deny it.\""), .cross("Nobody told you to do this, did they?", "\"No. It was my own idea, and I'm the only one responsible for it.\"")],
        openings: ("At midnight, the lobby camera in an apartment building shows {D} light a fuse and leave. A minute later a firecracker burst inside the mailbox bank, splitting the boxes and causing $540 in damage. The earlier case against {DL} was heard here in {PRIORDATE} when the case concerned {PRIOR}.", "{DL} admits it was a prank and that {D.he} did not think about what a firecracker would do inside a metal box. Nobody was near, nobody was hurt, and the defense will show a foolish act, not a malicious one."),
        closings: ("The video shows {D} light the fuse and leave, and the mailboxes split open a minute later. {DL} was last before this court in {PRIORDATE} after being charged with {PRIOR}. A prank that costs a landlord $540 is still willful damage to property.", "{DL} lit a firecracker as a prank when no one was around. {D.He} did not aim at anyone or intend to break the boxes, and {D.he} has promised to pay for them and apologize to the residents."),
        timeline: [(0, "Midnight: {D} lights a fuse in the lobby and leaves."), (0, "12:01 a.m.: the firecracker bursts and splits the mailbox bank."), (1, "The landlord finds the damage and reviews the lobby camera.")],
        identified: "Lobby Camera",
        mood: .indifferent)

    static let dumpsterAgain = SmallCases.make(
        key: "story.followup.dumpsterAgain",
        category: .publicOrder,
        headlines: ["Man Returns to Second Store Dumpster After Notice"],
        law: "trespass2",
        spec: "Entered and remained on the premises of {V}, a bakery, after being notified not to, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} dug through a bakery dumpster after a second written notice.",
        state: [E(.document, 3, "Trespass Notice", "Second signed notice.")],
        defense: [E(.statement, 1, "Discarded", "{DL} says the food was thrown out.")],
        role: "Bakery owner",
        exam: [.direct("Please tell the jury about your bakery.", "\"I own a small neighborhood bakery. I bake early in the morning, sell breads and pastries at the counter, and throw out what doesn't sell at the end of the day.\""), .direct("Had you spoken to {D} before that morning?", "\"Yes. I'd found {DL} at my dumpster before, and I gave {D.him} a written notice not to come on my property.\""), .direct("What happened after the first notice?", "\"A few weeks later, I found {DL} there again. I gave {D.him} a second written notice, and {D.he} signed it at the back door.\""), .direct("What did you see on the day you called the sheriff?", "\"At about five in the morning, I came in to bake and saw {DL} inside the fence, digging through the dumpster.\""), .direct("What was in the dumpster?", "\"Day-old bread, unsold pastries and some boxes. It's food we throw away because we can't sell it after a day.\""), .direct("Why does the notice matter to you?", "\"The back lot has equipment, deliveries and a loading dock. I can't have people in there at night, for their safety and mine.\""), .cross("Did {DL} take anything of value from the dumpster?", "\"Only food that we'd already thrown out. I'm not claiming a loss of goods.\""), .cross("Was the dumpster lock cut?", "\"Yes, the padlock had been cut. I don't know whether {D.he} did it, and I never saw {D.him} do it.\""), .cross("Did {DL} threaten you or your staff?", "\"No. {D.He} was polite and quiet the times I spoke to {D.him}.\""), .cross("Did {DL} say why {D.he} was there?", "\"{D.He} told me {D.he} was hungry. I believe {D.he} was telling the truth.\""), .cross("Would you have objected if {DL} had asked you for food?", "\"I probably would have given {D.him} some bread, if I'd been asked.\"")],
        theory: ("{D} dug through a bakery dumpster after already having been given two written notices not to return.", "The food in the dumpster had been thrown out, and {DL} was only looking for something to eat."),
        allocution: "\"I was hungry, and I went back to that bakery's dumpster after a second written notice. I've been in this courtroom before, and I know I'm not supposed to be there. I'll go to the food pantry instead, and I won't dig there again.\"",
        truths: ("{DL} signed both trespass notices, and the dumpster lock was cut before the food was taken.", "The bakery had thrown the food out as waste, and {DL} was hungry."),
        defendant: [.direct("Did you go back to the bakery's dumpster after the notices?", "\"Yes, I did. I was hungry, and I knew it was wrong, and I went anyway.\""), .direct("Did you sign both notices?", "\"Yes. I signed the first and the second, and I understood that I wasn't supposed to be on that property.\""), .direct("Why did you go back?", "\"I hadn't eaten in a day and a half, and I knew the bakery threw out good bread every morning. I couldn't afford anything.\""), .direct("What were you looking for in the dumpster?", "\"Just food. Day-old bread, rolls, anything that wasn't spoiled. I didn't take anything else or touch any of the equipment.\""), .direct("How did you get into the lot?", "\"The gate was open, and the lock on the dumpster had been broken before I arrived. I never cut anything.\""), .direct("What will you do instead?", "\"I'm going to the food pantry. They told me I can come three times a week, and I won't dig there again.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know I'm not supposed to be there. I wasn't thinking about anything but food.\""), .cross("You were warned twice, weren't you?", "\"Yes, in writing, and I signed both. I don't have an excuse except that I was hungry.\""), .cross("You knew you could be arrested for being there, didn't you?", "\"I did. I thought no one would see me that early in the morning.\""), .cross("The bakery asked you to stay away, didn't it?", "\"It did, politely, and I shouldn't have ignored it.\""), .cross("You could have gone to a pantry, couldn't you?", "\"Yes, and now I will. I'd been told about it and didn't go.\"")],
        openings: ("A bakery owner twice gave {D} a signed written notice not to come on the property. At five in the morning, deputies found {D} at the bakery dumpster, and The court file shows {DL} here in {PRIORDATE} over {PRIOR}.", "{DL} was hungry and went to the dumpster for food the bakery had thrown away. {D.He} does not dispute the notices, and the defense will ask you to consider what was in that dumpster and why {D.he} was there."),
        closings: ("The notice was served twice, {D} signed it twice, and {DL} still went back to the dumpster. {DL} stood in this court once before, in {PRIORDATE} where the matter was {PRIOR}. A written notice means something, and the law protects a business's back lot.", "The food was thrown out and abandoned, and {D} was hungry. {DL} has promised to use the food pantry instead. No one was harmed, and nothing the bakery wanted was taken."),
        timeline: [(-20, "The bakery owner serves {D} with a first written notice."), (-5, "{D} signs a second notice at the bakery's back door."), (0, "5 a.m.: deputies find {D} at the dumpster and arrest {D.him}.")],
        identified: "Trespass Notice",
        mood: .indifferent,
        genders: ["D": .male])

    static let shelterAgain = SmallCases.make(
        key: "story.followup.shelterAgain",
        category: .property,
        headlines: ["Rock Breaks Pane at Second Bus Shelter"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured real property of {V}, a transit authority, causing damage of $950, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} threw a rock through another shelter pane.",
        state: [E(.video, 3, "Shelter Camera", "{D} throws a rock.")],
        defense: [E(.statement, 1, "Anger", "{DL} says the bus skipped the stop.")],
        role: "Transit supervisor",
        exam: [.direct("Please tell the jury about your work for the transit authority.", "\"I'm a transit supervisor. I oversee drivers, routes and shelters, and I handle damage reports from the field.\""), .direct("What damage was reported?", "\"A pane of safety glass in a shelter on a busy route was shattered. There were chunks of glass across the sidewalk and into the bus lane.\""), .direct("What does the shelter camera show?", "\"It shows {D} waiting, a bus passing without stopping, and then {DL} picking up a rock and throwing it at the pane.\""), .direct("Did the shelter have other damage?", "\"The frame was bent a little where the rock hit, and one panel had to be replaced entirely.\""), .direct("What did the repair cost?", "\"The glass, the frame and the labor came to $950, which the authority had to cover from its maintenance budget.\""), .direct("Why do the shelters matter to the authority?", "\"Riders depend on them for cover in bad weather, and a broken pane can leave a stop unusable until we fix it.\""), .cross("Did the bus skip the stop that day?", "\"The driver's log shows the bus passed that stop without stopping because of a late-running schedule.\""), .cross("How long after the rock was thrown did the next bus come?", "\"About two minutes after the throw, according to the camera and the dispatch log.\""), .cross("Did {DL} complain to the authority about the bus?", "\"Yes, {D.he} left a message that same afternoon about the skipped stop.\""), .cross("Was anyone near the shelter when the rock was thrown?", "\"Not that the camera shows. The sidewalk was empty.\""), .cross("Did {DL} stay at the scene?", "\"No. {D.He} walked away after the throw.\"")],
        theory: ("{D} threw a rock through a bus shelter pane after a bus skipped the stop, repeating the same act as before.", "The bus skipped the stop, and {DL}'s anger came out in a single throw that {D.he} regrets."),
        allocution: "\"The bus skipped my stop, and I was angry, and I threw a rock through that shelter's glass. I've been in this room before for doing the same thing. I'll pay for the pane, and I'll stand and wait next time.\"",
        truths: ("{DL} threw the rock twice, with a second throw after the glass first cracked.", "The bus arrived two minutes after the rock was thrown, which shows how short the delay was."),
        defendant: [.direct("Did you throw the rock through the shelter pane?", "\"Yes, I did. I was angry, and I threw it. I know that was wrong.\""), .direct("Why were you so angry?", "\"I'd been waiting forty minutes in the cold on the way to a job, and when the bus finally came, it drove right past me.\""), .direct("Did you throw the rock more than once?", "\"The first throw cracked the glass, and I threw a second time. I was out of control for a moment.\""), .direct("What happened after that?", "\"I walked away and sat on a curb down the street. A couple of minutes later, I saw the bus I'd been waiting for come along.\""), .direct("How do you feel about it now?", "\"I'm ashamed. The shelter wasn't to blame, and other riders depend on it. I let my anger get ahead of me.\""), .direct("What do you plan to do?", "\"I'll pay for the pane, and next time I'll call the transit line or wait for the next bus.\""), .cross("You have been in this court before for the same thing, haven't you?", "\"Yes, and I promised myself it wouldn't happen again. I'm embarrassed to be back.\""), .cross("You picked up the rock on purpose, didn't you?", "\"I did. I picked it up and threw it. I won't claim it was an accident.\""), .cross("The rock went through the glass, didn't it?", "\"It did, and the glass shattered all over the sidewalk. Someone could have been hurt.\""), .cross("You left without telling the authority, didn't you?", "\"I did. I should have stayed and called someone.\""), .cross("The bus came two minutes later, didn't it?", "\"It did. If I'd waited, I'd have caught it.\"")],
        openings: ("A transit shelter pane was shattered by a rock, and the shelter camera shows {D} throw it, causing $950 in damage. The court file shows {DL} here in {PRIORDATE} where the matter was {PRIOR}.", "{DL} had waited for a bus that drove past the stop and acted in anger. {D.He} does not deny throwing the rock, and the defense will ask you to see a single outburst, one that {D.he} has promised to pay for."),
        closings: ("The shelter camera shows {D} throw a rock through the pane, and the damage was $950. The earlier case against {DL} was heard here in {PRIORDATE} over {PRIOR}. The same act, in the same place, is a pattern.", "A bus drove past the stop, and {D} threw a rock out of anger. The bus arrived two minutes later. The pane is paid for, and {DL} has said sorry and will wait next time."),
        timeline: [(0, "{D} waits at the shelter as a bus skips the stop."), (0, "Moments later: {D} throws a rock through the shelter pane."), (0, "The next bus arrives two minutes after the pane breaks.")],
        identified: "Shelter Camera",
        mood: .indifferent)

    static let sealcoatSecond = SmallCases.make(
        key: "story.followup.sealcoatSecond",
        category: .whiteCollar,
        headlines: ["Driveway Crew Takes Deposits in Second County"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $1,100, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} took $1,100 for a parking-lot sealcoat and left a thin coat.",
        state: [E(.physical, 3, "Lot", "The coat flakes by hand.")],
        defense: [E(.statement, 1, "Cold", "{DL} says it was too cold to cure.")],
        role: "Church secretary",
        exam: [.direct("Please tell the jury about your role at the church.", "\"I'm the church secretary. I handle our bills, contracts and maintenance calls, and I arranged to have the parking lot sealed.\""), .direct("How did you come to hire {D}?", "\"{DL} came to the office, handed me a card and offered to seal our lot for $1,100, which was a lot cheaper than other bids.\""), .direct("What did the work look like when it was finished?", "\"The lot looked dark and fresh, but the coat seemed thin. I could see the old cracks right through it.\""), .direct("What did you notice a few weeks later?", "\"The coat started to flake, and I could scrape it with a fingernail. In places, it was already coming off in sheets.\""), .direct("What did you pay?", "\"$1,100, by check, the day the work was finished. I'd been told the job came with a guarantee.\""), .direct("What happened when you called {DL}?", "\"I left messages, and {DL} told me the weather was to blame. I asked for a refund, and I didn't get one.\""), .cross("Did {DL} do the work as agreed on the contract?", "\"The contract said to seal the lot, and {D.he} did put something on it. The question is the quality.\""), .cross("Was the weather cold the day the lot was sealed?", "\"It was cool that morning, around fifty degrees, I believe.\""), .cross("Did {DL} offer to come back and fix it?", "\"Eventually, {D.he} did. By then I'd already called the sheriff.\""), .cross("Did anyone else look at the coat?", "\"A paving company looked at it and said the coat was too thin and had been thinned with water.\""), .cross("Did {DL} ever refuse to meet you?", "\"No. {D.He} came by once and looked at the lot with me.\"")],
        theory: ("{D} took $1,100 to seal a church parking lot and applied a thin coat that flakes off by hand.", "The weather was too cold for the sealer to cure, and the thin coat was a result of conditions, not a plan to cheat."),
        allocution: "\"It was cold when we sealed that lot, and I know the coat came out thin. I took eleven hundred dollars and I should have waited for better weather. I've been in this courtroom before, and I'll redo the work or refund the customer.\"",
        truths: ("The forecast called for warm weather, and the drums of sealer were watered down to stretch the job.", "The forecast turned cold overnight, and {DL} had only one day on the schedule."),
        defendant: [.direct("Did you seal the church lot for $1,100?", "\"Yes, I did. I took the job and the money, and the coat came out too thin. I admit that.\""), .direct("Why was the coat so thin?", "\"It was cold that morning, and the sealer was slow to spread and cure. I was in a hurry to finish before the temperature dropped.\""), .direct("Did you thin the sealer?", "\"I added a little water to help it spread. I shouldn't have, and I should have waited for a better day.\""), .direct("Why didn't you wait?", "\"I had other jobs lined up, and I'd quoted the church a firm price. I felt I couldn't push it back.\""), .direct("What did you do when the church called?", "\"I went to look at the lot with the secretary. I told her I'd redo the work, but I didn't have the money for materials right then.\""), .direct("What are you willing to do now?", "\"I'll redo the lot in warm weather at no charge, or refund the church. They can choose.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I should have been more careful about this job. I know how it looks.\""), .cross("The forecast was warm earlier in the week, wasn't it?", "\"It was, and I should have waited for that day. I moved the job to save time.\""), .cross("You watered down the sealer, didn't you?", "\"A little. I know it was wrong, and I won't do it again.\""), .cross("You kept the money, didn't you?", "\"I did, for a few weeks. I can pay it back now.\""), .cross("The coat flakes off by hand, doesn't it?", "\"Yes, I've seen it myself. It's a bad coat, and I take responsibility.\"")],
        openings: ("A church paid {D} $1,100 to seal its parking lot, and within weeks the coat flaked off by hand. The sealer had been thinned. This is not {DL}'s first time here, since {PRIORDATE} brought {D.him} in once already where the matter was {PRIOR}.", "{DL} admits the coat came out thin because it was cold when the lot was sealed. {D.He} should have waited for better weather, and the defense asks you to see a poor job, not a deliberate fraud."),
        closings: ("A church paid $1,100 for a sealcoat that flakes off with a fingernail. The drums were watered down, and the forecast was warm. {DL} has appeared in this courtroom before, back in {PRIORDATE} where the matter was {PRIOR}. This is a thin coat sold as a full one.", "The weather turned cold, and the coat did not cure. {D} has offered to redo the work or refund the church. A badly done job is a contract dispute, not a fraud."),
        timeline: [(-30, "{D} quotes the church $1,100 for sealing the parking lot."), (-14, "{D} seals the lot on a cool day with a thin coat."), (0, "The church secretary finds the coat flaking and calls deputies.")],
