        exam: [.direct("Please tell the jury about your job at the gym.", "\"I'm a front desk clerk. I check members in, answer questions, and keep an eye on the lobby and the cubbies where members leave their things.\""), .direct("How do the cubbies work?", "\"Members put their phones, wallets and keys in open cubbies near the front desk while they work out. They're not locked.\""), .direct("What was reported that day?", "\"A member told me that a phone with a blue case had gone missing from a cubby. I checked the lobby camera.\""), .direct("What did the camera show?", "\"It shows {D} reaching into a cubby, lifting a phone, and walking out through the side door.\""), .direct("What was the phone worth?", "\"About $450. It was fairly new, and the member told me it had family photos on it.\""), .direct("Did you speak to {DL}?", "\"Yes, a couple of days later when {DL} came back. {D.He} seemed upset and said {D.he} had taken it by mistake.\""), .cross("Did {DL} have a phone of {D.his} own at the gym?", "\"Yes. {D.He} had a phone in a bag, and it looks much like the one that was taken.\""), .cross("Were the two phones in cubbies next to each other?", "\"I believe they were, yes, but I don't know for sure.\""), .cross("Did {DL} try to hide the phone?", "\"Not that I could see. {D.He} carried it in {D.his} hand.\""), .cross("Did {DL} return the phone?", "\"{D.He} said {D.he} would. I'm not sure it has been returned yet.\""), .cross("Was {DL} a regular at the gym?", "\"Yes. {D.He} comes a few times a week.\"")],
