    static let garagePass = SmallCases.make(
        key: "story.followup.garagePass",
        category: .whiteCollar,
        headlines: ["Man Forges Hospital Garage Pass"],
        law: "forgery",
        spec: "Forged a parking pass of {V}, a hospital, on {DATE}.",
        ages: 18...60,
