        defense: [E(.statement, 1, "Invited", "{DL} says a guest invited {D.him}.")],
        role: "Hall manager",
        exam: [.direct("Please tell the jury about your job.", "\"I'm the manager of the private hall. I rent the space for parties and weddings, handle the staff and make sure only invited guests are inside.\""), .direct("What event was going on that day?", "\"A retirement party for a longtime teacher, with about sixty guests. The family had given me a guest list.\""), .direct("What did you see?", "\"A person I didn't recognize, {D}, was at the buffet filling a plate. {D.He} wasn't on the list, and no one at the party knew {D.him}.\""), .direct("What did you say to {DL}?", "\"I walked up and told {D.him} it was a private party and asked {D.him} to leave. {D.He} nodded but stayed.\""), .direct("What happened next?", "\"I asked a second time a few minutes later. {D.He} stayed again, and I called the sheriff's office.\""), .direct("What does the hall camera show?", "\"{DL} entering through the front door, going straight to the buffet, filling a plate and sitting at an empty table.\""), .cross("Did {DL} cause any trouble at the party?", "\"No. {D.He} ate quietly and didn't bother anyone.\""), .cross("Did a guest wave {DL} into the hall?", "\"I saw someone at the door gesture toward the buffet. I can't say whether it was an invitation.\""), .cross("Did any guest say they knew {DL}?", "\"No. I asked around, and nobody did.\""), .cross("Did {DL} argue with you when you asked {D.him} to leave?", "\"No. {D.He} was polite and said {D.he} didn't mean to cause a problem.\""), .cross("Did the family complain about {DL}?", "\"The family said it didn't matter, but I felt I had to follow the rules for the event.\"")],
        theory: ("{D} joined a private retirement party uninvited and ignored two requests to leave.", "A guest waved {D.him} in, and {DL} believed {D.he} was welcome."),
        allocution: "\"I joined that retirement party after eating nearby, and I ignored two requests to leave. I've been in this courtroom before for doing the same. It was embarrassing and wrong. I'll apologize to the family.\"",
        truths: ("No guest at the party knew {DL}, and the hall manager asked {D.him} twice to leave.", "One guest waved {DL} in, and {D.he} stayed a short time, eating and talking."),
        defendant: [.direct("Did you go to the retirement party without an invitation?", "\"Yes, I did. A guest waved me in, and I thought I was welcome, so I went in and ate.\""), .direct("Who waved you in?", "\"A man at the door, who gestured toward the food and smiled at me. I took it as an invitation to come in.\""), .direct("Why did you stay after the manager asked you to leave?", "\"I was embarrassed, and I thought I could finish my plate and leave. I should have gone right away.\""), .direct("Had you eaten that day?", "\"Not much. I'd been short on money, and the smell of the food drew me in.\""), .direct("Did you cause any trouble?", "\"No. I sat at an empty table and kept to myself. I didn't speak to anyone.\""), .direct("What will you do about it?", "\"I'll apologize to the family, and I won't go to any event I'm not invited to.\""), .cross("You have been in this court before for doing the same thing, haven't you?", "\"Yes, and it was embarrassing and wrong. I should have learned.\""), .cross("The manager asked you twice to leave, didn't she?", "\"Yes, she asked me twice, and I didn't go the first time or the second. I'm sorry for the trouble.\""), .cross("Nobody there knew you, did they?", "\"No, I didn't know anyone there, and I should have realized that meant I wasn't invited.\""), .cross("You took food that wasn't meant for you, didn't you?", "\"I did, and I know that wasn't right.\""), .cross("You could have asked someone before going in, couldn't you?", "\"I could have, and I'll ask next time.\"")],
