        closings: ("The hall camera shows {D} filling a plate at a private party where no one knew {D.him}. The manager asked {D.him} to leave twice, and {D.he} stayed. {DL} was no stranger to this courtroom after {PRIORDATE} in a case for {PRIOR}. Being asked to leave means leave.", "A guest waved {D} in, and {D} believed {D.he} was welcome. {DL} stayed only a short time and caused no trouble. {D.He} has said that {D.he} will apologize to the family."),
        timeline: [(0, "Afternoon: the retirement party begins at the hall."), (0, "{D} walks in and fills a plate at the buffet."), (0, "The hall manager asks {D} to leave twice, and calls deputies when {D.he} stays.")],
        identified: "Hall Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let scooterTwo = SmallCases.make(
        key: "story.followup.scooterTwo",
        category: .property,
        headlines: ["Rider Keeps Rental E-Bike for Two Weeks"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a bike company, valued at $900, on {DATE}.",
        ages: 18...60,
