        defense: [E(.statement, 1, "Forgot", "{DL} says {D.he} forgot to end the ride.")],
        role: "Company agent",
        exam: [.direct("Please tell the jury about your role at the company.", "\"I'm an agent for the bike company. I track our bikes, respond to reports of missing equipment and contact customers when a ride runs too long.\""), .direct("How did you learn that a bike was missing?", "\"The app showed a bike that had been in the same place for days, with the ride still marked as active.\""), .direct("What did the app record?", "\"The ride started at a downtown dock, and then the bike moved to a residential address and stayed there for two weeks.\""), .direct("What did you do about it?", "\"We sent a series of alerts and texts to the customer, who didn't reply. After a week I called, and nobody answered.\""), .direct("What was the bike worth?", "\"About $900. It's an electric model with a locked battery, and they're expensive to replace.\""), .direct("How was the bike recovered?", "\"The deputies went to the address and found it in {D}'s garage. It was undamaged, but the battery was dead.\""), .cross("Did {DL} reply to any of your messages?", "\"No. We sent several, and I don't have any record of a reply.\""), .cross("Was the battery dead for most of the time?", "\"It looks that way. The app stopped reporting its charge after a couple of days.\""), .cross("Did {DL} hide the bike?", "\"It was in the garage, not in plain view. I can't say whether that was to hide it.\""), .cross("Does {DL} owe the company money?", "\"The meter would have run up a large charge for a two-week ride. It hasn't been paid.\""), .cross("Has this happened with other customers?", "\"It happens now and then, usually because someone forgets.\"")],
        theory: ("{D} kept a rental e-bike at home for two weeks and ignored the company's messages.", "{DL} forgot to end the ride, and the battery died, leaving the bike where it was."),
        allocution: "\"I kept that rental e-bike at home for two weeks and ignored the messages. I've been in this courtroom before about the same thing. I'll pay what I owe and return it today.\"",
        truths: ("The app sent alerts, and the bike stayed parked at {D}'s home for fourteen days.", "The battery was dead for most of that time, and {DL} did not realize the ride was still running."),
        defendant: [.direct("Did you keep the e-bike at your home for two weeks?", "\"Yes, I did. I forgot to end the ride, and I ignored the messages when they started coming in.\""), .direct("Why did you ignore the messages?", "\"I thought they were just ads or reminders, and then I felt embarrassed about how long it had been. I should have answered.\""), .direct("Why was the bike at your home?", "\"I rode it home from downtown because I was late for work. I meant to return it the next day.\""), .direct("What happened to the battery?", "\"It died after a day or two. I didn't know how to charge it, so I left it in the garage.\""), .direct("Did you ever try to sell or hide the bike?", "\"No. I never touched it again after the battery died. It sat there.\""), .direct("What will you do now?", "\"I'll return the bike today and pay what I owe.\""), .cross("You have been in this court before about the same thing, haven't you?", "\"Yes, and I should have known better after the first time. I'm embarrassed to be here again.\""), .cross("You knew the company wanted its bike back, didn't you?", "\"I did, eventually, and I should have called them.\""), .cross("The alerts went out for two weeks, didn't they?", "\"Yes, for two weeks, and I ignored every one of them. I'm sorry that I did.\""), .cross("You didn't return it, did you?", "\"No, not until now, and I'm sorry that it took a court case to make me bring it back.\""), .cross("You could have left it at a dock, couldn't you?", "\"I could have left it at a dock the moment I got home, and I wish I had done that.\"")],
