        closings: ("The app shows the bike parked at {D}'s home for two weeks, and the company sent alerts that went unanswered. The bike was worth $900. {DL} was last before this court in {PRIORDATE} after being charged with {PRIOR}. Keeping a rental bike for weeks is taking it.", "{DL} forgot to end the ride, and the battery died. {D} did not sell or hide the bike, and has offered to return it and pay what is owed."),
        timeline: [(0, "{D} starts a rental ride and takes the e-bike home."), (7, "The company app sends alerts that the ride has not ended."), (14, "The company traces the bike to {D}'s home and reports it.")],
        identified: "App Record",
        mood: .indifferent)

    static let pokerChips = SmallCases.make(
        key: "story.followup.pokerChips",
        category: .whiteCollar,
        headlines: ["Man Cashes Altered Chips at Second Casino"],
        law: "falsePretenses",
        spec: "Obtained property of {V}, a casino, by deception, $650, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} tried to cash altered chips at a second casino.",
        state: [E(.physical, 3, "Chips", "Chips with altered edges.")],
        defense: [E(.statement, 1, "Won", "{DL} says {D.he} won them.")],
        role: "Casino cashier",
        exam: [.direct("Please tell the jury about your job at the casino.", "\"I'm a cashier at the casino cage. I count chips, exchange them for cash and watch for counterfeit or altered chips every shift.\""), .direct("What happened when {D} came to your window?", "\"{DL} put a stack of chips on the counter and asked to cash out. They looked slightly off to me right away.\""), .direct("What was wrong with the chips?", "\"The edges were thicker in places and the inlay didn't match. They had been altered, probably to pass as a higher denomination.\""), .direct("What was the total value of the chips?", "\"At the denominations they were meant to resemble, they added up to about $650.\""), .direct("What did you do?", "\"I pressed the silent alarm and kept {DL} talking while security came. Then security held {DL} until the deputies arrived.\""), .direct("How do you know the chips were altered?", "\"We compare the weight, the edge pattern and the inlay against genuine chips. These didn't match on any of the three.\""), .cross("Did {DL} seem surprised when you called security?", "\"Yes. {D.He} said {D.he} didn't know they had been altered, and {D.he} looked genuinely shocked.\""), .cross("Did {DL} try to leave the window or hide the chips?", "\"No. {D.He} stayed where {D.he} was and answered every question calmly.\""), .cross("Did you see {DL} alter the chips?", "\"No. I only saw them at my window. I have no idea who handled them before that.\""), .cross("Do you know where {DL} got the chips?", "\"{D.He} told security {D.he} won them at another casino. I haven't confirmed that.\""), .cross("Can an ordinary player tell when chips have been altered?", "\"Not easily. It takes a trained eye, and I only caught it because I do this all day.\"")],
        theory: ("{D} tried to cash altered casino chips worth $650 at a second casino.", "{DL} won the chips fairly at a poker table and had no idea they had been altered."),
        allocution: "\"I won those chips at the table, and I tried to cash them in, and I thought they were good. I've been in this courtroom before at a casino, and I know how that looks.\"",
        truths: ("The chips had altered edges, and the cashier recognized the alteration at once.", "A pit boss at the first casino watched {DL} win those chips at a table."),
        defendant: [.direct("Did you try to cash those chips?", "\"Yes, I did. I'd won them at a table, and I took them to the cashier to cash out.\""), .direct("Where did you win them?", "\"At a poker table at the first casino, over a few hours. A pit boss watched the table and saw me win those hands.\""), .direct("Did you know the chips were altered?", "\"No. I had no idea. They looked and felt like any other chips to me, and I'd never looked at them closely.\""), .direct("What did you do when security stopped you?", "\"I told them exactly where I'd won the chips and gave them my name. I answered every question they asked.\""), .direct("Have you ever altered chips or known how?", "\"No. I wouldn't know how to begin, and I would never risk a casino ban for a few hundred dollars.\""), .direct("What will you do now?", "\"I'll cooperate fully with the court and anyone investigating, and I'll ask the first casino to confirm my win.\""), .cross("You have been in this court before at a casino, haven't you?", "\"Yes, and I realize how this looks to the court. I didn't alter these chips or know about them.\""), .cross("You tried to cash chips worth $650, didn't you?", "\"Yes, I did. I believed they were mine, and I still believe I won them fair and square.\""), .cross("You didn't examine the chips before you cashed them, did you?", "\"No, I didn't. I never thought to look at the edges, and I wouldn't have known what to look for.\""), .cross("You played at both casinos that night, didn't you?", "\"Yes, I played at both. I won at the first, and I went to the second to cash out because it was closer to my car.\""), .cross("A pit boss isn't here to confirm your win, is he?", "\"Not today, no, but the first casino has records of my play and I'd like the court to see them.\"")],
        openings: ("At a second casino's cage, a cashier looked at the chips {D} handed over and saw altered edges. The chips were worth $650, and {DL} was in front of this court earlier, in {PRIORDATE} over {PRIOR}.", "{DL} says {D.he} won the chips at a poker table at the first casino, where a pit boss saw the win. The defense will show that {D.he} had no idea the chips were altered, and that {D.he} cooperated fully with the cashier, security and deputies."),
        closings: ("A casino cashier found altered edges on chips worth $650, and {D} was the one trying to cash them. {DL} has appeared in this courtroom before, back in {PRIORDATE} where the matter was {PRIOR}. Cashing altered chips is obtaining money by deception.", "A pit boss saw {D} win those chips at a table. {DL} did not alter them and never knew anyone had. Someone who stays at the window and cooperates is not acting like a cheat."),
        timeline: [(0, "Evening: {D} plays poker and wins a stack of chips at the first casino."), (0, "{D} brings the chips to the cage at a second casino and asks to cash out."), (0, "The cashier notices altered edges and calls security, who hold {D} for deputies.")],
        identified: "Chips",
        mood: .indifferent,
        genders: ["D": .male])

    static let tithePlate = SmallCases.make(
        key: "story.followup.tithePlate",
        category: .property,
        headlines: ["Man Takes Tithes From Another Church Plate"],
        law: "misdLarceny",
        spec: "Stole property of {V}, a church, valued at $400, on {DATE}.",
