        defense: [E(.statement, 1, "Counting", "{DL} says {D.he} was helping count.")],
        role: "Church usher",
        exam: [.direct("Please tell the jury about your role at the church.", "\"I'm an usher at the church. I collect the offering plates, carry them to the counting room and help keep an eye on the money until it's counted.\""), .direct("What happened after the service that Sunday?", "\"The plates were brought to the counting table. {D} came over and offered to help count, and I didn't see a reason to say no.\""), .direct("What does the sanctuary camera show?", "\"{DL} sorting bills and, at one point, sliding a few into a jacket pocket. {D.He} did that more than once during the count.\""), .direct("How much was missing?", "\"The count came to about $400 less than the ushers expected based on the plates. It was a large offering that week.\""), .direct("How does the church normally control the count?", "\"Two counters sign a sheet each week before they touch the money. No one counts alone, and the sheet goes in a safe.\""), .direct("What did you do after you saw the footage?", "\"I told the pastor and the head usher, and we called the sheriff's office with the recording.\""), .cross("Was a sign-in sheet used that Sunday?", "\"No. The head usher was out, and the sheet wasn't put out that week.\""), .cross("Did anyone ask {DL} to help count?", "\"I believe someone told {D.him} it was fine. I didn't stop {D.him}.\""), .cross("Did {DL} try to hide the money?", "\"It went into a pocket, but I can't say what was in {D.his} mind.\""), .cross("Did {DL} offer to repay the church?", "\"Yes, through a friend, {D.he} said {D.he} would pay it all back.\""), .cross("Is {DL} a member of your church?", "\"I've seen {D.him} at a few services, but I wouldn't say {D.he} is a regular member.\"")],
        theory: ("{D} pocketed cash from a church collection plate while counting it.", "{DL} was helping the counters, and no sign-in sheet was used that day."),
        allocution: "\"I was helping count the plate, and I took some cash in my pocket while I counted. There was no sign-in sheet. I've been in this courtroom before about the same. I'll repay every dollar to the church.\"",
        truths: ("Counters sign a sheet each week, and {DL} signed none while pocketing cash on camera.", "There was no sign-in sheet that day, and {DL} was invited to help count."),
        defendant: [.direct("Did you put the church's cash in your pocket?", "\"Yes, I did, while I was sorting the bills. I know how it looked, and I regret it.\""), .direct("Why were you helping with the count?", "\"An usher told me they needed help, and I offered. Nobody gave me a sheet to sign.\""), .direct("Why did you put cash in your pocket?", "\"I was hurried, and I used my pocket to sort the small bills. Then I took some and didn't put them back. I was in a bad spot with money.\""), .direct("How much did you take?", "\"About $400, I think. I haven't spent any of it, and I'm ready to give every dollar back.\""), .direct("What did you do when you were confronted?", "\"I admitted that I'd been careless with the cash, and I offered to repay it right away.\""), .direct("What do you plan to do now?", "\"I'll repay every dollar to the church, and I won't touch their money again.\""), .cross("You have been in this court before about the same thing, haven't you?", "\"Yes, and I know I should have known better. I'm ashamed of it.\""), .cross("No other counter put money in a pocket, did they?", "\"Not that I saw. I'm the one who did it.\""), .cross("You were not asked to help by the head usher, were you?", "\"No. It was another usher, and I should have waited.\""), .cross("The camera shows you more than once, doesn't it?", "\"Yes, and I can't explain that except to say that I was weak.\""), .cross("You haven't paid the church back yet, have you?", "\"Not yet. I'm going to as soon as the court allows.\"")],
        openings: ("At a second church, the sanctuary camera shows {D} slip cash from a collection plate into a pocket during the count. About $400 was missing, and {DL} stood in this court once before, in {PRIORDATE} over {PRIOR}.", "{DL} says {D.he} was helping the counters and put the money in a pocket while sorting bills. The defense will show that no sign-in sheet was used that day, and that {D.he} has offered to repay every dollar."),
        closings: ("The sanctuary camera shows {D} slipping cash from the plate into a pocket, and $400 was missing. Counters sign a sheet each week, and {DL} signed nothing. {DL} already has a history in this court, dating to {PRIORDATE} after being charged with {PRIOR}. The plate belongs to the church.", "There was no sign-in sheet that day, and {D} was helping count. A pocket is not proof of intent to keep the money. {DL} will repay every dollar to the church."),
        timeline: [(0, "Sunday: the congregation gives, and ushers bring the plates forward."), (0, "After the service: {D} helps count and slips cash into a pocket on camera."), (0, "The counters find the total $400 short and review the camera.")],
        identified: "Sanctuary Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let fakeTempTag = SmallCases.make(
        key: "story.followup.fakeTempTag",
