        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} had unlabeled hydrocodone pills at a gas station.",
        state: [E(.forensic, 3, "Lab Report", "Six tablets of hydrocodone.")],
        defense: [E(.statement, 1, "Friend's", "{DL} says a friend asked {D.him} to hold them.")],
        role: "Deputy",
        exam: [.direct("Please tell the jury about your job.", "\"I'm a deputy with the sheriff's office. I patrol the county, and I make traffic stops and respond to calls, including drug complaints.\""), .direct("What led you to approach {D}?", "\"I was called to a gas station about a car sitting at a pump for a long time with the engine running.\""), .direct("What did you find?", "\"{DL} was in the car, and I saw a small plastic bag with white tablets sticking out of a pocket.\""), .direct("What did the lab report say?", "\"That there were six tablets of hydrocodone, a Schedule II controlled substance.\""), .direct("Did {DL} have a prescription?", "\"No. {D.He} said {D.he} didn't, and there was no label or pharmacy bag.\""), .direct("What did {DL} tell you?", "\"{D.He} said the pills were a friend's, and {D.he} had been asked to hold them. {D.He} showed me a text.\""), .cross("Did {DL} show you the text from the friend?", "\"Yes. It said something about picking the pills up later that evening.\""), .cross("Did you see {DL} take any of the pills?", "\"No. There was nothing to suggest {D.he} had used any.\""), .cross("Did {DL} try to hide the pills?", "\"They were in {D.his} pocket, and {D.he} handed them over when I asked.\""), .cross("Did you speak to the friend?", "\"I tried, but the friend did not respond.\""), .cross("Did you find money or scales?", "\"No, there was nothing like that.\"")],
        theory: ("{D} was found with six unlabeled hydrocodone tablets at a gas station and had no prescription.", "{DL} was holding the pills for a friend and never meant to keep or use them."),
