    static let bootsOut = SmallCases.make(
        key: "story.followup.bootsOut",
        category: .property,
        headlines: ["Customer Wears New Boots Out of Store"],
        law: "larcenyMerchant",
        spec: "Took merchandise valued at $210 from {V}, a boot store, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} wore store boots out the door.",
        state: [E(.video, 3, "Store Camera", "{D} walks out in new boots.")],
        defense: [E(.statement, 1, "Forgot", "{DL} says {D.he} forgot.")],
        role: "Store clerk",
        exam: [.direct("Please tell the jury about your job.", "\"I'm a clerk at a boot store. I help customers find sizes, ring up sales and watch the floor for anything unusual.\""), .direct("What did you notice that day?", "\"A customer left, and I saw an old pair of boots in a box on the bench where a new pair should have been.\""), .direct("What does the store camera show?", "\"It shows {D} trying on a pair of new boots, putting the old ones in the box and walking out the front door in the new pair.\""), .direct("What were the boots worth?", "\"$210. They were a work boot we sell a lot of, and they're expensive.\""), .direct("Did {DL} stop at the register?", "\"No. {D.He} walked right past it and out the door.\""), .direct("What did you do?", "\"I told my manager, and we called the sheriff's office. We gave them the footage.\""), .cross("Did {DL} return to the store?", "\"Yes. {D.He} came back that afternoon and spoke to a clerk.\""), .cross("What did {DL} say?", "\"{D.He} said {D.he} had forgotten to pay and wanted to settle up.\""), .cross("Did {DL} try to hide the boots?", "\"No. {D.He} wore them openly.\""), .cross("Did {DL} pay?", "\"{D.He} offered to, but the deputies had already been called.\""), .cross("Was the old pair worth anything?", "\"They were worn out, and we couldn't resell them.\"")],
        theory: ("{D} wore a pair of store boots out the door without paying.", "{DL} tried the boots on, forgot to pay and came back to correct it."),
        allocution: "\"I put the boots on to try them and then walked out wearing them, distracted, without ever going to the register. I'll pay for them today, and I'm sorry to the store for the trouble. I won't let it happen again.\"",
        truths: ("Old boots were left in a box, and the camera shows {D} walking out in the new pair.", "{DL} came back to the store after leaving and tried to pay."),
        defendant: [.direct("Did you walk out of the store in the new boots?", "\"Yes, I did. I put them on to try them, and I forgot to pay and walked out wearing them.\""), .direct("Why did you forget to pay?", "\"I was distracted by a phone call about my kids, and I walked out while I was still on the phone. It was careless.\""), .direct("What did you do with your old boots?", "\"I left them in the box on the bench. They were worn through, and I planned to throw them away anyway.\""), .direct("When did you realize you hadn't paid?", "\"That evening, when I took the boots off at home and saw the price sticker on the sole. I felt sick about it.\""), .direct("What did you do then?", "\"I went back to the store the next day, found a clerk and told her what happened. I offered to pay right then.\""), .direct("What will you do now?", "\"I'll pay for the boots today, and I'm sorry to the store for the trouble I caused.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know how that looks to anyone watching the camera. I'm not proud of it.\""), .cross("You walked right past the register, didn't you?", "\"I did, with my phone to my ear. I didn't even look at it, and I should have.\""), .cross("You left your old boots behind in the box, didn't you?", "\"Yes, because I planned to throw them out. I know that can look like a switch.\""), .cross("You came back only after the footage was reviewed, didn't you?", "\"No, I came back that afternoon, before I knew anyone had checked the camera.\""), .cross("You wore the new boots in front of the camera the whole time, didn't you?", "\"Yes, in plain view the whole way out. I didn't hide anything.\"")],
        openings: ("At a boot store, the camera shows {D} walk out the front door wearing a pair of new boots worth $210, leaving an old pair in the box. {DL} was last before this court in {PRIORDATE} for {PRIOR}.", "{DL} says {D.he} tried the boots on and walked out distracted, forgetting to pay. The defense will show that {D.he} came back to the store to settle it and has offered to pay."),
        closings: ("The store camera shows {D} wearing new boots out the door and leaving worn ones in the box. They were worth $210. The earlier case against {DL} was heard here in {PRIORDATE} on the earlier matter, {PRIOR}.", "{DL} tried them on, forgot to pay and came back to the store. A person who returns and offers to pay did not mean to steal."),
        timeline: [(0, "{D} tries on boots at the store and leaves the old pair in the box."), (0, "{D} walks out the door wearing the new boots."), (0, "Later: {D} returns to the store.")],
