        mood: .indifferent)

    static let scooterRiver = SmallCases.make(
        key: "story.followup.scooterRiver",
        category: .property,
        headlines: ["Man Throws Rental Scooter Into Creek"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a scooter company, causing damage of $800, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} threw a rental scooter into a creek.",
        state: [E(.video, 3, "Bridge Camera", "{D} lifts the scooter over the rail.")],
        defense: [E(.statement, 1, "Dare", "{DL} says it was a dare.")],
        role: "Company agent",
        exam: [.direct("Please tell the jury about your job with the company.", "\"I'm an agent for the scooter company. I track our fleet, respond to reports of missing or damaged scooters and coordinate recovery crews.\""), .direct("How did you learn the scooter was missing?", "\"The app showed a scooter that had gone dark on a bridge near the creek. The last location was in the middle of the bridge.\""), .direct("What did you find?", "\"Our recovery crew pulled the scooter out of the creek the next morning. The frame was bent, and the battery and the motor were ruined.\""), .direct("What does the bridge camera show?", "\"It shows {D} carrying the scooter to the rail with a friend nearby, lifting it up and dropping it into the water.\""), .direct("What was the damage?", "\"The scooter was a total loss, and the bill for the recovery and the replacement came to about $800.\""), .direct("How did you identify {DL}?", "\"The rental app has an account name, and the camera shows the plate of a car parked near the bridge. Both came back to {DL}.\""), .cross("Did {DL} film the throw?", "\"Yes. A phone video shows it, and it was posted to a social account for a little while.\""), .cross("Was anyone near the creek when the scooter fell?", "\"No. The creek was empty, and nobody was hurt.\""), .cross("Did {DL} contact the company afterward?", "\"{D.He} called a few days later and offered to pay for the scooter.\""), .cross("Does the app show whether the rider ended the ride properly?", "\"No, the ride was still active when the scooter went into the water.\""), .cross("Was the friend identified?", "\"I don't believe so. The footage shows the friend only from behind.\"")],
        theory: ("{D} lifted a rental scooter over a bridge rail and threw it into a creek.", "A friend dared {DL}, and {D.he} threw the scooter without thinking about the cost."),
        allocution: "\"A friend dared me, and I threw that rental scooter into the creek. I've been in this courtroom before for something similar. I know it was stupid, and I'll help pay for it.\"",
        truths: ("The scooter was reported missing the same night, and {DL} filmed the throw on a phone.", "{DL}'s friend dared {D.him}, and the friend egged {D.him} on throughout."),
        defendant: [.direct("Did you throw the rental scooter into the creek?", "\"Yes, I did. A friend dared me, and I lifted it over the rail and let it go. It was stupid.\""), .direct("Why did you do it?", "\"It was a dare, and I wanted to look tough. I didn't think about the cost, or about the company, or about the people who use the scooters.\""), .direct("Why did you film it?", "\"My friend filmed it first, and then I filmed a second take. We were laughing, and I never thought it would end up as evidence.\""), .direct("What did you feel afterward?", "\"Embarrassed and sick. It was a waste, and I'd damaged something that wasn't mine. I took the video down the next day.\""), .direct("What did you do about the scooter?", "\"I called the company a few days later and offered to pay. I hadn't known whether I should call first.\""), .direct("What will you do now?", "\"I'll help pay for it, and I'll stay away from dares like that.\""), .cross("You have been in this court before for something similar, haven't you?", "\"Yes, and I know better. I'm embarrassed to be here again over a dare.\""), .cross("Nobody forced you to throw it, did they?", "\"No. A dare isn't force, and I made the choice myself.\""), .cross("You filmed the throw, didn't you?", "\"Yes. I know how that looks.\""), .cross("The scooter was a total loss, wasn't it?", "\"That's what the company says, and I accept that.\""), .cross("You waited a few days to call the company, didn't you?", "\"I did, and I should have called right away.\"")],
        openings: ("A bridge camera shows {D} lift a rental scooter over the rail and drop it into a creek, causing $800 in damage to the scooter company's property. {DL} filmed the throw. This is not {DL}'s first time here, since {PRIORDATE} brought {D.him} in once already in the case known as {PRIOR}.", "{DL} says a friend dared {D.him}, and {D.he} did it without thinking about the cost. The defense will show an act of foolishness that {D.he} regrets and has offered to repay."),
        closings: ("The bridge camera shows {D} lifting a rental scooter over the rail and dropping it into the creek. {DL} even filmed it. The company lost $800, and {DL} was no stranger to this courtroom after {PRIORDATE} where the matter was {PRIOR}.", "A friend dared {D}, and {D} acted without thinking. {D.He} is sorry and has offered to pay for the scooter. This was a foolish act from a person who now understands the cost."),
        timeline: [(0, "Night: {D} and a friend walk onto the bridge with a rental scooter."), (0, "{D} lifts the scooter over the rail and drops it into the creek."), (1, "The scooter company reports the scooter missing and recovers it from the water.")],
        identified: "Bridge Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let hedgeCut = SmallCases.make(
        key: "story.followup.hedgeCut",
        category: .property,
        headlines: ["Neighbor Cuts Hedge Down Over Property Line"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured real property of {V}, causing damage of $900, on {DATE}.",
        ages: 18...60,
