        state: [E(.document, 3, "Survey", "The hedge stood on {V}'s side.")],
        defense: [E(.statement, 1, "Line", "{DL} says the line is disputed.")],
        role: "Neighbor",
        exam: [.direct("Please tell the jury about your property and the hedge.", "\"I own the lot next to {D}. The hedge ran along our shared line for about thirty years, and it gave us privacy and shade.\""), .direct("What did you find when you came home that day?", "\"The hedge was gone. It had been cut down to stumps and the clippings were piled on my side.\""), .direct("How do you know the hedge was on your side?", "\"I had a survey done a month before. It showed the hedge stood about a foot inside my property line.\""), .direct("What did it cost to replace?", "\"Between the loss of the mature plants and the cost to plant new ones, the damage came to about $900.\""), .direct("Had {DL} said anything about the hedge before?", "\"A few times, {DL} said it grew over {D.his} side, and I said I'd trim it. We never agreed on where the line was.\""), .direct("How did you feel about it?", "\"I was angry and sad. That hedge was part of my home, and it will take years to grow back.\""), .cross("Did {DL} have a survey of {D.his} own?", "\"Not that I know of. I think {D.he} relied on an old fence line.\""), .cross("Was there an old fence along the line?", "\"There was a rusted fence on part of it. The fence isn't on the line, according to the survey.\""), .cross("Did {DL} offer to pay for the hedge?", "\"Yes, {D.he} did. I haven't taken the money.\""), .cross("Did {DL} apologize?", "\"Yes, in person, a few days later.\""), .cross("Did you show {DL} your survey before the cutting?", "\"No. I should have, and I'm sorry that I didn't.\"")],
        theory: ("{D} cut down a neighbor's hedge, claiming it sat on {D.his} lot.", "{DL} believed the hedge was on {D.his} lot based on an old line, and never ordered a survey."),
        allocution: "\"I believed that hedge was on my lot, and I cut it down based on an old line. I've been in this courtroom before about a tree. I should have gotten a survey. I'll pay for the hedge.\"",
        truths: ("A recent survey shows the hedge stood on {V}'s side of the line.", "{DL} never ordered a survey of {D.his} own, and relied on an old fence line."),
        defendant: [.direct("Did you cut down the hedge?", "\"Yes, I did. I believed it was on my lot, and I cut it down with a chainsaw.\""), .direct("Why did you believe it was on your lot?", "\"An old fence ran along the line, and the hedge was mostly on my side of it. I thought that was the boundary.\""), .direct("Did you get a survey?", "\"No, I didn't, and I should have. I relied on the fence and on what the previous owner told me.\""), .direct("Did you talk to your neighbor first?", "\"We had spoken about the hedge a few times, but never about cutting it. I should have asked before I did anything.\""), .direct("How did you feel when you learned about the survey?", "\"Sick. I'd made a mistake that I couldn't undo, and I'd hurt a neighbor over a bad assumption.\""), .direct("What will you do now?", "\"I'll pay for the hedge and the new plants, and I'll apologize again.\""), .cross("You have been in this court before about a tree, haven't you?", "\"Yes, and I should have been much more careful than I was. I'm embarrassed to be here again.\""), .cross("The survey shows the hedge on {V}'s side, doesn't it?", "\"Yes, and I accept that now. I should have checked before I cut.\""), .cross("You didn't get {V}'s permission, did you?", "\"No, I didn't, and I should have asked.\""), .cross("You used a chainsaw, didn't you?", "\"Yes. It took less than an hour.\""), .cross("You have not paid for the hedge yet, have you?", "\"Not yet. I've offered, and I'll do it as soon as the court allows.\"")],
        openings: ("A neighbor's hedge was cut to the ground, and a recent survey shows it stood on {V}'s side of the property line. The damage was about $900, and {DL} has appeared in this courtroom before, back in {PRIORDATE} when the case concerned {PRIOR}.", "{DL} says {D.he} believed the hedge was on {D.his} lot, based on an old line. The defense will show a boundary mix-up, not a deliberate attack, and an owner who has offered to pay for the hedge."),
        closings: ("The survey shows the hedge stood on {V}'s side of the line, and {D} cut it to the ground. It cost $900 to replace. {DL} returns to this court having been here in {PRIORDATE} in a case for {PRIOR}.", "{D} believed the hedge was on {D.his} own lot and cut it based on an old line. {DL} should have gotten a survey, and has offered to pay for the hedge. A boundary mistake is not malice."),
        timeline: [(-30, "{V} has the property surveyed and finds the hedge on {V.his} side."), (0, "{D} cuts the hedge to the ground with a chainsaw."), (0, "{V} comes home to find the hedge gone.")],
        identified: "Survey",
        mood: .indifferent)

    static let redirectedPackages = SmallCases.make(
        key: "story.followup.redirectedPackages",
        category: .property,
        headlines: ["Man Redirects Ex-Girlfriend's Packages to Own Door"],
