        spec: "Stole property of {V}, valued at $450, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} redirected a former partner's package deliveries and kept four.",
        state: [E(.digital, 3, "Carrier Notice", "Redirect requested from {D}'s account.")],
