        role: "Former partner",
        exam: [.direct("Please tell the jury about your relationship to {D}.", "\"{DL} and I were partners for a few years. We split up a while ago, and we've had very little contact since then.\""), .direct("What happened with your packages?", "\"Several packages I'd ordered never arrived. I tracked them, and the carrier told me the delivery address had been changed.\""), .direct("How was the address changed?", "\"The carrier's notice shows a redirect request from {DL}'s account. It sent my packages to {DL}'s address.\""), .direct("What was in the packages?", "\"Clothes, a small appliance and some books. Together they were worth about $450.\""), .direct("Did {DL} tell you about it?", "\"No. I found out from the carrier. I didn't hear from {D.him} until the deputies called.\""), .direct("What did you get back?", "\"One package was returned to me. The others haven't been, as far as I know.\""), .cross("Did {DL} return one of the packages?", "\"Yes. It was left on my porch.\""), .cross("Did {DL} say why {D.he} redirected the deliveries?", "\"{D.He} said it was a mistake with an account, and I don't know how it works.\""), .cross("Did you and {DL} share an account while you were together?", "\"We did, for deliveries, and I never closed it.\""), .cross("Did {DL} offer to pay for the rest?", "\"Through the deputies, yes. {DL} offered to pay for the rest through the deputies.\""), .cross("Had you changed your address recently?", "\"Yes, and I think that's how the confusion began.\"")],
        theory: ("{D} redirected a former partner's package deliveries and kept four of them.", "{DL} redirected the deliveries by mistake and kept four packages before realizing what had happened."),
        allocution: "\"I redirected my former partner's deliveries by mistake, and I kept four of the packages before I understood what I'd done. I've been in this courtroom before, and I know that's wrong. I'll return everything I still have and pay for what's gone.\"",
        truths: ("The redirect was requested from {DL}'s own account, and four packages were kept.", "One package was returned, which shows {DL} did not mean to keep them all."),
        defendant: [.direct("Did you redirect {V}'s packages?", "\"Yes, I did, but it was a mistake. We'd shared a delivery account while we were together, and I changed something without realizing.\""), .direct("How did the mistake happen?", "\"I was updating my address with the carrier and clicked a box that moved all the deliveries on the old shared account. I didn't read it closely.\""), .direct("Why did you keep four packages?", "\"They came to my door, and I opened them thinking they were mine. By the time I understood, I'd used a few of the things.\""), .direct("What did you do with the one you returned?", "\"I took it to {V}'s porch as soon as I realized whose it was.\""), .direct("What have you done about the others?", "\"I've told the deputies where they are, and I'll return what I still have.\""), .direct("What will you do about the rest?", "\"I'll pay for whatever is gone, and I'll stay away from any shared account.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know it's wrong. I should have checked the account settings before clicking anything.\""), .cross("You opened packages addressed to {V}, didn't you?", "\"Yes, but I thought they were mine at first.\""), .cross("You used some of the items, didn't you?", "\"A few, and I'll pay for them.\""), .cross("You didn't tell {V} right away, did you?", "\"No, and I should have.\""), .cross("You kept four of them, didn't you?", "\"Yes. I'm sorry. I kept four of them, and I shouldn't have.\"")],
        openings: ("A former partner's package deliveries were redirected to a new address, and the carrier notice shows the redirect was requested from {D}'s account. Four packages worth $450 were kept, and {DL} already has a history in this court, dating to {PRIORDATE} over {PRIOR}.", "{DL} says the redirect was a mistake, and that one package was returned as soon as {D.he} understood. The defense will show a confused account change, not a plan to take anything."),
        closings: ("The carrier notice shows the redirect was requested from {D}'s account, and four packages were kept. They were worth $450. The earlier case against {DL} was heard here in {PRIORDATE} over {PRIOR}.", "{DL} says the redirect was an account mistake, and one package was returned. {D} will return everything {D.he} still has and pay for what is gone."),
        timeline: [(0, "A redirect request is made from {D}'s account for a former partner's deliveries."), (5, "Four packages arrive at {D}'s address and are kept."), (10, "The former partner finds the packages missing and calls deputies.")],
        identified: "Carrier Notice",
        mood: .indifferent,
        genders: ["D": .male])

    static let cardsFound = SmallCases.make(
        key: "story.followup.cardsFound",
