        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} used cards from a found purse for $380.",
        state: [E(.video, 3, "Store Camera", "{D} swipes the cards.")],
        defense: [E(.statement, 1, "Return", "{DL} says {D.he} meant to return it.")],
        role: "Cardholder",
        exam: [.direct("Please tell the jury what happened to your purse.", "\"I lost my purse at a bus stop on a busy afternoon. I realized it was gone when I reached for my keys at my front door.\""), .direct("What was in the purse?", "\"My wallet with two credit cards and a debit card, my license, some cash and a few personal items. My address was on the license.\""), .direct("What did you do when you noticed it was gone?", "\"I called my bank right away and canceled the cards. That's when I learned that three charges had already been made.\""), .direct("What were the charges for?", "\"A few stores, including clothes, groceries and gas. Altogether they came to about $380.\""), .direct("What did the store camera show?", "\"It shows {D} swiping my cards at the registers, three separate times, in different stores.\""), .direct("Did you get the purse back?", "\"A deputy returned it a few days later. The cash and the cards were gone, but my license and the other items were there.\""), .cross("Did the purse have your address in it?", "\"Yes, on my license and on a prescription label.\""), .cross("Did {DL} contact you to return the purse?", "\"No. I only heard from {D.him} through the deputy.\""), .cross("Has the bank reversed the charges?", "\"Most of them, yes. The bank covered the loss.\""), .cross("Did {DL} offer to repay you?", "\"Yes. {DL} offered to repay me through the deputy.\""), .cross("Did you see {DL} take your purse?", "\"No. I know only what the camera shows.\"")],
        theory: ("{D} found a purse and used the cards in it for $380 in purchases.", "{DL} found the purse meaning to return it, and used the cards before doing so."),
        allocution: "\"I found that purse and meant to return it, and I used the cards before I did. I've been in this courtroom before, and I know that's wrong. I'll repay the three hundred eighty dollars.\"",
        truths: ("{DL} used the cards three times at stores, and the purse had an address on a card inside.", "The purse had the owner's address in it, and {DL} meant to return it."),
        defendant: [.direct("Did you use the cards from the purse?", "\"Yes, I did. I found the purse, and I used the cards before I returned it, and I know that was wrong.\""), .direct("Where did you find it?", "\"On a bench near the bus stop. It was sitting alone, and nobody was around to ask about it.\""), .direct("Why didn't you return it right away?", "\"I meant to. I looked at the license and saw the address, but I was short on money that week, and I made a bad choice.\""), .direct("How many times did you use the cards?", "\"Three times, for clothes, groceries and gas. I'm sorry I did, and I'm ashamed of how easily I talked myself into it.\""), .direct("What did you do with the purse after that?", "\"I put it in a bag and meant to take it to the owner's address. The deputies found it before I could.\""), .direct("What will you do now?", "\"I'll repay the $380, and I'll apologize to {V} in person if {V.he} will let me.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I know using someone else's cards is wrong. I should have turned the purse in right away.\""), .cross("The owner's address was in the purse, wasn't it?", "\"Yes, on the license, and I read it. I should have gone straight there instead of to a store.\""), .cross("You swiped the cards three times, didn't you?", "\"Yes, three times in three different places, and I'm sorry for each one of them.\""), .cross("You kept the cash from the purse, didn't you?", "\"Yes, I did. It's gone, and I'll pay it back along with the rest.\""), .cross("The camera shows you clearly at each register, doesn't it?", "\"Yes, it does. I'm not going to say it wasn't me.\"")],
