    static let storeGrabRun = SmallCases.make(
        key: "story.followup.storeGrabRun",
        category: .property,
        headlines: ["Group Grabs Jackets at Outlet and Runs"],
        law: "larcenyMerchant",
        spec: "Took merchandise valued at $540 from {V}, an outlet store, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} grabbed jackets and ran from an outlet store.",
