        role: "Store manager",
        exam: [.direct("Please tell the jury about your job.", "\"I'm the manager of the outlet store. I supervise the staff, handle loss prevention and review the camera when merchandise goes missing.\""), .direct("What happened that afternoon?", "\"Two people came in and walked to the jacket rack. A few minutes later, they grabbed several jackets and ran out the front door.\""), .direct("What does the store camera show?", "\"{D} and another person pulling jackets off the rack, and {DL} running out the door with several in {D.his} arms.\""), .direct("What was the value of the merchandise taken?", "\"About $540. They were new-season jackets at full price.\""), .direct("How did deputies find {DL}?", "\"A deputy responding to our call stopped {DL} a block away. {D.He} had one jacket on {D.him}.\""), .direct("What happened to the rest of the jackets?", "\"We haven't recovered them. The other person ran in a different direction.\""), .cross("Did {DL} grab the jackets first?", "\"I can't say. The video shows both of them pulling at the same time.\""), .cross("Did {DL} carry more than one jacket out of the store?", "\"The video shows {D.him} with an armful, but only one was found.\""), .cross("Do you know the identity of the other person?", "\"No. We haven't identified {D.him}.\""), .cross("Did {DL} cooperate with the deputy?", "\"Yes. {D.He} gave up the jacket and answered questions.\""), .cross("Did {DL} offer to pay for the jackets?", "\"Through the deputy, yes. {DL} offered to pay for the jackets that way.\"")],
        theory: ("{D} grabbed jackets and ran out of an outlet store with a friend.", "A friend grabbed the jackets, and {DL} ran only because the friend ran, ending up with one jacket."),
