        truths: ("{DL} was found with one jacket, and the camera shows {D.him} running with an armful.", "The friend who grabbed the rest has not been found."),
        defendant: [.direct("Did you run out of the store with the jackets?", "\"Yes, I did. I grabbed one jacket and ran when my friend ran, and I'm not proud of it.\""), .direct("Who was your friend?", "\"Someone I'd met a few weeks earlier. I've told the deputies his name, but I don't know where he lives.\""), .direct("Who grabbed the jackets?", "\"My friend pulled most of them off the rack. I picked one up and followed him out of the door.\""), .direct("Why did you run?", "\"My friend ran, and I panicked. I didn't think about the camera or what it meant.\""), .direct("What happened when the deputy stopped you?", "\"I handed over the jacket, and told him everything I knew about my friend. I didn't try to run again.\""), .direct("What will you do now?", "\"I'll pay for what I took, and I'll stay away from the people who got me into it.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I should have just walked out of that store with nothing.\""), .cross("You had an armful of jackets on camera, didn't you?", "\"It looks that way. I dropped most of them as I ran.\""), .cross("You can't prove who your friend is, can you?", "\"Not with a document. I can only give the name.\""), .cross("You ran because you knew it was wrong, didn't you?", "\"I ran because I was scared, and I knew it was wrong.\""), .cross("You kept one jacket, didn't you?", "\"Yes. I should have left it too.\"")],
        openings: ("At an outlet store, the camera shows {D} running out the door with jackets worth $540. Deputies stopped {D} a block away with one jacket, and The court file shows {DL} here in {PRIORDATE} where the matter was {PRIOR}.", "{DL} says a friend grabbed the jackets, and {D.he} ran when the friend did. The defense will show that {D.he} ended up with a single jacket, and that the friend who took the rest has not been found."),
        closings: ("The store camera shows {D} running with an armful of jackets worth $540, and a deputy found one on {D.him}. {DL} stood in this court once before, in {PRIORDATE} in a case for {PRIOR}. Running with stolen merchandise is the crime itself.", "A friend grabbed the jackets, and {D} ran when the friend ran. {DL} had one jacket, and has offered to pay for what {D.he} took. The friend is the one who planned this."),
        timeline: [(0, "Afternoon: {D} and a friend enter the outlet store."), (0, "The friend grabs several jackets, and both run out."), (0, "Deputies stop {D} a block away with one jacket.")],
        identified: "Store Camera",
        mood: .indifferent)

    static let paramedicSpit = SmallCases.make(
        key: "story.followup.paramedicSpit",
        category: .violent,
        headlines: ["Patient Spits on Paramedic"],
        law: "assaultGovOfficial",
        spec: "Assaulted a government employee, a paramedic, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} spit on a paramedic during treatment.",
        state: [E(.video, 3, "Ambulance Camera", "{D} spits.")],
        defense: [E(.statement, 1, "Confused", "{DL} says {D.he} was confused.")],
        role: "Paramedic",
        exam: [.direct("Please tell the jury about your job.", "\"I'm a paramedic. I respond to emergency calls, assess patients, start treatment and transport them to the hospital.\""), .direct("What was the call that day?", "\"A bystander called about a person who seemed confused and unsteady on a sidewalk. We found {D} sitting on the curb.\""), .direct("What did you find when you examined {DL}?", "\"{DL} was sweaty, disoriented and talking in disconnected sentences. I smelled alcohol, but the symptoms didn't fit with that alone.\""), .direct("What happened in the ambulance?", "\"As I checked a pulse, {DL} spat in my face. It hit my cheek and my mouth.\""), .direct("What does the ambulance camera show?", "\"{DL} leaning forward and spitting at me, and me pulling back. The footage is clear.\""), .direct("What did you do next?", "\"I finished the assessment and took {DL} to the hospital. I was exposed to bodily fluid, so I went through testing and a lot of worry.\""), .cross("Did you check {DL}'s blood sugar?", "\"Yes. It was dangerously low, and I treated it.\""), .cross("Did {DL} calm down after treatment?", "\"Yes. {D.He} improved and apologized, and {D.he} was embarrassed.\""), .cross("Had {DL} been drinking?", "\"There was some alcohol, but not enough to explain the symptoms.\""), .cross("Does low blood sugar cause confusion?", "\"Yes, and sometimes aggressive behavior.\""), .cross("Did {DL} threaten you?", "\"No, there were no threats. It was a sudden spit.\"")],
        theory: ("{D} spat on a paramedic during treatment in an ambulance.", "{DL} was confused from low blood sugar, and did not know where {D.he} was."),
        allocution: "\"I was confused when that paramedic was treating me, and I spit. I've been in this courtroom before, and I'm ashamed. I'll apologize to the crew and get help for what's behind it.\"",
        truths: ("{DL} was intoxicated, and the ambulance camera shows {D.him} spitting at the paramedic.", "The paramedic's own blood sugar check showed a dangerously low reading."),
        defendant: [.direct("Did you spit on the paramedic?", "\"Yes, I did. I don't remember it clearly, because my blood sugar was very low, and I was confused.\""), .direct("What do you remember from that day?", "\"I remember feeling shaky and sweaty and then waking up in the hospital. Pieces of the ambulance ride come back to me.\""), .direct("Why was your blood sugar low?", "\"I'd skipped meals and had been drinking, which can make it worse. I have a condition that I'm supposed to manage.\""), .direct("What did you do when you realized what happened?", "\"I apologized to the crew as soon as I understood. I was horrified, and I asked if the paramedic was okay.\""), .direct("Would you have done it if you'd been clear-headed?", "\"Never. I'd never do that, and I'm ashamed.\""), .direct("What will you do now?", "\"I'll apologize in person and get help for what's behind it, including my health.\""), .cross("You have been in this court before, haven't you?", "\"Yes, and I'm ashamed to be back. I should have been taking much better care of myself, and I let it get this far.\""), .cross("You had been drinking that day, hadn't you?", "\"Yes, I had some to drink that day, and I know it made the low blood sugar and my confusion a good deal worse.\""), .cross("You spat on someone trying to help you, didn't you?", "\"Yes, I did, and there is no good excuse. The paramedic was only trying to help me, and I'm truly sorry.\""), .cross("You have a condition that you need to manage, don't you?", "\"Yes, I do, and I wasn't managing it that week. I skipped meals and my medicine, and I paid the price for it.\""), .cross("The camera shows you clearly, doesn't it?", "\"Yes, it does, and I won't argue with it. I've watched it, and I can see how bad it looked.\"")],
        openings: ("An ambulance camera shows {D} spit on a paramedic who was treating {D.him}. The paramedic was a government employee doing the job, and {DL} was last before this court in {PRIORDATE} in the case known as {PRIOR}.", "{DL} was confused and acting from a medical emergency. A blood sugar reading shows a dangerously low level, and the defense will show that {D.he} did not know what {D.he} was doing."),
        closings: ("The ambulance camera shows {D} spitting on a paramedic who was trying to help. The earlier case against {DL} was heard here in {PRIORDATE} where the matter was {PRIOR}. Assaulting a paramedic is a crime, whatever the cause.", "A low blood sugar reading shows {D} was confused and acting from a medical emergency, not from malice. {DL} is ashamed, and has apologized to the crew."),
        timeline: [(0, "A call comes in for a person who is disoriented on the street."), (0, "The paramedic begins treatment, and {D} spits at {V.him}."), (0, "The paramedic completes a blood sugar test and finds a low reading.")],
        identified: "Ambulance Camera",
        mood: .indifferent,
        genders: ["D": .male])

    static let quadTrail = SmallCases.make(
        key: "story.followup.quadTrail",
        category: .traffic,
        headlines: ["ATV Rider Tears Through Greenway"],
        law: "recklessDriving",
        spec: "Drove carelessly and heedlessly in willful disregard of the rights and safety of others, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} rode an ATV down a greenway and scattered walkers.",
        state: [E(.video, 3, "Trail Camera", "{D} speeds past walkers.")],
        defense: [E(.statement, 1, "Trail", "{DL} says it was an open trail.")],
        role: "Park ranger",
        exam: [.direct("Please tell the jury about your job.", "\"I'm a park ranger. I patrol the greenway and the parks, enforce the posted rules and respond to complaints from the public.\""), .direct("What are the rules on the greenway?", "\"It's a paved trail for walkers, runners and cyclists. Motor vehicles aren't allowed, and there are signs at every entrance.\""), .direct("What did you see that day?", "\"I got a call about an ATV on the trail. I found {D} at the next trailhead, and several walkers told me what happened.\""), .direct("What does the trail camera show?", "\"{DL} riding fast down the middle of the trail, with walkers moving to the edges and jumping aside as {D.he} came by.\""), .direct("Were there signs at the entrance {DL} used?", "\"Yes, a no-motor-vehicles sign stands at that entrance. I checked afterward, and it was standing.\""), .direct("Was anyone hurt?", "\"Nobody was hit, but a woman with a stroller had to pull sharply to the side, and I thought it was close.\""), .cross("Could the sign have been hard to see from where {DL} entered?", "\"It was on a post a few feet off the path. A rider coming fast might miss it.\""), .cross("Did {DL} slow down when {D.he} saw the walkers?", "\"The video shows {D.him} slowing near the end, yes.\""), .cross("Did {DL} argue with you?", "\"No. {D.He} was polite and said {D.he} thought it was an open trail.\""), .cross("Did {DL} damage the trail?", "\"There were tire marks on the edge, and nothing serious.\""), .cross("Has {DL} been on the greenway before?", "\"Not to my knowledge. As far as I know, {DL} hasn't been on the greenway before.\"")],
        theory: ("{D} rode an ATV at speed down a greenway and scattered walkers.", "{DL} thought the greenway was an open trail and missed the no-motor-vehicle signs."),
        allocution: "\"I thought that greenway was an open trail, and I missed the sign. I've been in this courtroom before on an ATV. I scattered walkers, and I'll keep my machine off public paths.\"",
        truths: ("Signs at the trailhead say no motor vehicles, and the camera shows {D} speeding past walkers.", "No one was struck, and {DL} slowed when the walkers jumped aside."),
        defendant: [.direct("Did you ride your ATV down the greenway?", "\"Yes, I did. I thought it was an open trail, and I missed the sign at the entrance where I came in.\""), .direct("Why did you think it was open?", "\"It looked like the other trails I ride on, and I came in from a gravel lot where ATVs are allowed. I wasn't paying close attention.\""), .direct("How fast were you going?", "\"Faster than I should have been. The trail was smooth and open, and I didn't think about it. I slowed down as soon as I saw people.\""), .direct("Did you see the walkers?", "\"Yes, when I came around a bend. They moved to the sides, and I slowed right down and called out that I was sorry.\""), .direct("What did the ranger say when stopping you?", "\"The ranger told me it was a walking trail only, and I apologized right away. I'd had no idea.\""), .direct("What will you do now?", "\"I'll keep my machine off public paths, and I'll check every entrance and sign before I ride anywhere I haven't been.\""), .cross("You have been in this court before on an ATV, haven't you?", "\"Yes, I was, and I should have been much more careful this time. I'm sorry for what I put those walkers through.\""), .cross("You scattered walkers on the trail, didn't you?", "\"Yes, I did. I saw them jump aside, and I felt terrible about it right then.\""), .cross("There is a sign at the entrance, isn't there?", "\"Apparently there is, but I didn't see it. I should have looked for one before I rode in.\""), .cross("You rode past a woman with a stroller, didn't you?", "\"I did, and I'm sorry. I didn't see the stroller until I was almost beside it.\""), .cross("You could have gotten off and walked the machine, couldn't you?", "\"Yes, if I'd known it was closed to vehicles. I'd have turned around at once.\"")],
        openings: ("On a paved greenway posted against motor vehicles, a camera shows {D} speeding past walkers on an ATV, and several of them had to jump aside. No one was hit, and Court records have {DL} here before, in {PRIORDATE} where the matter was {PRIOR}.", "{DL} says {D.he} thought the greenway was an open trail and missed the signs. The defense will show that {D.he} slowed down when {D.he} saw the walkers, and that nobody was struck or hurt."),
        closings: ("Signs at the trailhead say no motor vehicles, and the camera shows {D} speeding past walkers on an ATV. The court file shows {DL} here in {PRIORDATE} where the matter was {PRIOR}. Riding an ATV through a crowd of walkers is carelessness.", "{D} thought the greenway was open, and slowed when {D.he} saw the walkers. No one was struck. {DL} will keep {D.his} machine off public paths from now on."),
        timeline: [(0, "Afternoon: {D} rides an ATV onto the greenway."), (0, "The trail camera shows {D} speeding past walkers who jump aside."), (0, "A park ranger stops {D} at the next trailhead.")],
        identified: "Trail Camera",
        mood: .indifferent)

    static let lostCatReward = SmallCases.make(
        key: "story.followup.lostCatReward",
        category: .whiteCollar,
        headlines: ["Man Demands Reward for Cat He Took From Porch"],
        law: "falsePretenses",
        spec: "Obtained property of {V} by deception, $200, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, {D} took a neighbor's cat and returned it for a $200 reward.",
        state: [E(.video, 3, "Porch Camera", "{D} carries the cat away.")],
        defense: [E(.statement, 1, "Found", "{DL} says the cat wandered up.")],
        role: "Owner",
        exam: [.direct("Please tell the jury about your cat.", "\"My cat is an orange tabby named Biscuit. We've had him for eight years, and he has never been gone more than a night.\""), .direct("How did the cat go missing?", "\"I let him out one morning, and he didn't come back for dinner. I looked all evening and put up flyers the next day.\""), .direct("What did the flyer say?", "\"It said 'Lost orange cat,' with a photo and my number, and offered a $200 reward. I'd have paid more to get him back.\""), .direct("What did your porch camera show?", "\"It shows {D} walking up to my porch and picking up the cat from the steps, and carrying him away.\""), .direct("How did you get the cat back?", "\"{DL} called me two days later and said {D.he} had found him. {D.He} brought him over and I gave {D.him} the $200.\""), .direct("When did you learn about the camera footage?", "\"A few days later, when I looked at the porch recording. I felt cheated, and I called the sheriff.\""), .cross("Was the cat indoors when {DL} picked it up?", "\"It was on the porch steps, by the door. It may have been outside, I'm not sure.\""), .cross("Did {DL} ask about the reward before bringing the cat?", "\"{D.He} asked on the phone whether the reward was still on. I told {D.him} it was.\""), .cross("Did the cat seem harmed?", "\"No. He was fed and clean, and he was glad to be home.\""), .cross("Did {DL} return the cat voluntarily?", "\"Yes, {D.he} did, after I told {D.him} it was my cat.\""), .cross("Has {DL} offered to return the reward?", "\"Yes. {DL} offered to return the reward through the deputy.\"")],
        theory: ("{D} took a neighbor's cat from the porch and returned it for a $200 reward.", "The cat wandered up on its own, and {DL} returned it in good faith and was offered the reward."),
        allocution: "\"I found that cat and took it home, and I took the reward when it was offered. I've been in this courtroom before for something like this. I'll return the two hundred dollars.\"",
        truths: ("The cat was indoors, and the porch camera shows {D} carrying it away.", "{DL} asked about a reward before returning the cat."),
        defendant: [.direct("Did you take the cat from the porch?", "\"I picked up a cat that came to me, and I carried it away. I honestly thought it was lost and needed help.\""), .direct("How did you come to have the cat?", "\"The cat wandered up to me on the sidewalk, and I followed it to a porch. I picked it up there, and I didn't see anyone around.\""), .direct("Why did you ask about the reward?", "\"I'd seen the flyer on a pole, and I asked whether it was still on. I thought it would be fine to accept thanks for bringing a pet home.\""), .direct("Did you know the cat belonged to your neighbor?", "\"Not at first. When I read the flyer and compared the photo, I realized it was the same cat, and I returned it.\""), .direct("Did you take the $200 reward?", "\"Yes, I did. I know now that it wasn't right to take money for it, and I will give every dollar back.\""), .direct("What will you do now?", "\"I'll return the two hundred dollars, and I'll apologize to the owner in person for the worry I caused over those two days.\""), .cross("You have been in this court before for something like this, haven't you?", "\"Yes, and I know how it looks to anyone hearing it. I'm ashamed that I put myself in this position again.\""), .cross("The camera shows you carrying the cat away from the porch, doesn't it?", "\"Yes, it does, and I don't deny it. I was trying to help a cat I thought was lost.\""), .cross("You called about the reward before you brought the cat back, didn't you?", "\"Yes, I did. I asked whether it was still being offered, and I can see now that I shouldn't have.\""), .cross("The cat was at the owner's door when you picked it up, wasn't it?", "\"Yes, it was on the steps by the door, and I should have knocked and asked before touching it.\""), .cross("You kept the cat for two days, didn't you?", "\"I did, and I'm sorry for that. I should have gone to the owner's house the very first day.\"")],
        openings: ("A neighbor's cat vanished, and a lost-cat flyer offered a $200 reward. The porch camera shows {D} carrying the cat away, and {D} later brought it back and collected the money. {DL} has appeared in this courtroom before, back in {PRIORDATE} over {PRIOR}.", "{DL} says the cat wandered up on its own, and {D.he} returned it in good faith. The defense will show that {D.he} did not take it from a closed home, and that {D.he} has offered to return the $200."),
        closings: ("The porch camera shows {D} carrying the cat away, and then {D} collected a $200 reward for returning it. {DL} was in front of this court earlier, in {PRIORDATE} for {PRIOR}. Taking a pet and collecting a reward is deception.", "The cat wandered up to {D}'s porch, and {D} returned it as any neighbor would. {DL} was offered the reward and took it. {D.He} has offered to give the $200 back."),
        timeline: [(0, "The neighbor's cat goes missing, and a flyer offers a $200 reward."), (1, "The porch camera shows {D} carrying the cat away."), (2, "{D} returns the cat and collects the reward.")],
        identified: "Porch Camera",
        mood: .indifferent,
        genders: ["D": .male])

